function redo(){if(cur>=snapshots.length-1)return;cur++;applyState(snapshots[cur].st);renderAll();toast('已重做 → <b>#'+(cur+1)+' '+esc(snapshots[cur].label)+'</b>');}
function restore(k){
  if(k<0||k>=snapshots.length||k===cur)return;
  applyState(snapshots[k].st);
  commit('回退至 #'+(k+1),'时间旅行');
  toast('已回退至快照 <b>#'+(k+1)+'</b>（已记为新快照，可继续撤销）');
}
function resetAll(){
  state.projection=INIT.projection;state.measure=INIT.measure;
  state.filters={};state.selection=new Set();state.focus={};
  commit('重置全部','账本');toast('已重置全部状态（可撤销恢复）');
}

/* ---------- 派生 ---------- */
function passes(o){for(const[d,s]of Object.entries(state.filters))if(!s.has(o[d]))return false;return true;}
function filteredRows(){return ORDERS.filter(passes);}
function aggBy(rows,dimId,m){
  const res=new Map();for(const v of DIMS[dimId].values)res.set(v,{sum:0,n:0,segs:[0,0,0,0]});
  for(const r of rows){const e=res.get(r[dimId]);if(!e)continue;e.sum+=m.acc(r);e.n++;e.segs[SEGMENTS.indexOf(r.segment)]++;}
  for(const e of res.values())e.val=e.n?(m.agg==='avg'?e.sum/e.n:e.sum):0;
  return res;
}

/* ---------- 格式化 ---------- */
function fmtInt(n){return n.toLocaleString('zh-CN');}
function fmtMoney(v){return v<1e4?'¥'+Math.round(v):v<1e8?'¥'+(v/1e4).toFixed(1)+'万':'¥'+(v/1e8).toFixed(2)+'亿';}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function vlabel(d,v){return DIMS[d].label(v);}

/* ---------- 动作 ---------- */
function setProjection(dim,source){
  if(state.projection===dim)return;
  state.projection=dim;
  commit('投影 → 「'+DIMS[dim].name+'」',source);
  const f=state.focus[dim];
  if(f)requestAnimationFrame(()=>{const el=document.querySelector('.tile[data-val="'+CSS.escape(f)+'"]');
    if(el){el.scrollIntoView({block:'nearest'});el.classList.add('flash');}});
  toast('已切换投影 → <b>「'+DIMS[dim].name+'」</b> · 认知已保留：选中 '+state.selection.size+' 项 · 过滤 '+Object.keys(state.filters).length+' 维');
}
function toggleFilter(dim,val,source){
  const f=state.filters[dim]||new Set();
  if(f.has(val))f.delete(val);else f.add(val);
  state.focus[dim]=val;
  if(f.size===0)delete state.filters[dim];else state.filters[dim]=f;
  const on=state.filters[dim]&&state.filters[dim].has(val);
  commit((on?'过滤 ':'取消 ')+DIMS[dim].name+'='+vlabel(dim,val),source);
}
function removeFilterValue(dim,val){
  const f=state.filters[dim];if(!f)return;
  f.delete(val);if(f.size===0)delete state.filters[dim];
  commit('移除过滤值 '+DIMS[dim].name+'='+vlabel(dim,val),'账本');
}
function clearDim(dim){if(!state.filters[dim])return;delete state.filters[dim];commit('清空过滤 '+DIMS[dim].name,'账本');}
function drill(deptVal){
  state.filters.dept=new Set([deptVal]);state.projection='cat';state.focus.dept=deptVal;
  commit('下钻 「'+vlabel('dept',deptVal)+'」 → 品类','下钻');
  toast('已下钻至<b>品类</b>（范围=该部门，记入过滤账本，可回退）');
}
function setMeasure(mk){
  if(state.measure===mk)return;state.measure=mk;
  commit('度量 → '+MEASURES[mk].name,'度量切换');
}
function toggleSelect(id){
  if(state.selection.has(id))state.selection.delete(id);else state.selection.add(id);
  commit((state.selection.has(id)?'选中 ':'取消 ')+id,'明细行点击');
}

