      +(dim==='dept'?'<button class="drill" data-act="drill" data-val="'+esc(v)+'" title="范围=该部门，投影切至品类（记入账本）">下钻品类 ▸</button>':'')
      +'</div>';
  }
  $('#tiles').innerHTML=html;
  const empty=$('#tilesEmpty');
  if(rows.length===0){empty.hidden=false;empty.textContent='范围内没有订单——调整或移除过滤（账本中可单条回退）。';}
  else empty.hidden=true;
}

