      +'<div id="selNote">跨维度 · 跨过滤保留'+(out?'<span class="warn"> · '+out+' 项当前在范围外</span>':'')+'</div>';
  }
  html+='</div>';
  /* 快照历史（时间旅行） */
  html+='<div class="sec"><h3>快照历史<span class="n">'+snapshots.length+'</span><span class="prov">点击任意条=回退到该状态</span></h3><div id="snaplist">';
  for(let i=snapshots.length-1;i>=0;i--){
    const s=snapshots[i];
    html+='<button class="snap'+(i===cur?' cur':'')+'" data-act="restore" data-k="'+i+'" title="回退到 #'+(i+1)+'">'
      +'<span class="k">#'+(i+1)+'</span><span>'+esc(s.label)+'</span><span class="src">'+esc(s.source)+' '+s.time+'</span></button>';
  }
  html+='</div></div>';
  $('#ledger').innerHTML=html;
}

/* ---------- toast ---------- */
let toastTimer=null,scenarioMode=false;
function toast(html,pin){
  const el=$('#toast');el.innerHTML=html;el.classList.add('show');
  clearTimeout(toastTimer);
  if(!pin&&!scenarioMode)toastTimer=setTimeout(()=>el.classList.remove('show'),2800);
}

/* ---------- 事件 ---------- */
document.addEventListener('click',e=>{
  const el=e.target.closest('[data-act]');if(!el)return;
  switch(el.dataset.act){
    case 'project':setProjection(el.dataset.dim,'维度轨');break;
    case 'tile':toggleFilter(el.dataset.dim,el.dataset.val,'值卡点击');break;
    case 'drill':drill(el.dataset.val);break;
    case 'measure':setMeasure(el.dataset.m);break;
    case 'row':toggleSelect(el.dataset.id);break;
    case 'unval':removeFilterValue(el.dataset.dim,el.dataset.val);break;
    case 'clearDim':clearDim(el.dataset.dim);break;
    case 'unsel':state.selection.delete(el.dataset.id);commit('移除选中 '+el.dataset.id,'账本');break;
    case 'clearSel':state.selection.clear();commit('清除选择集','账本');break;
    case 'undo':undo();break;
    case 'redo':redo();break;
    case 'reset':resetAll();break;
    case 'restore':restore(+el.dataset.k);break;
  }
});
/* 值卡键盘可达 */
document.addEventListener('keydown',e=>{
  if((e.ctrlKey||e.metaKey)&&!e.shiftKey&&e.key.toLowerCase()==='z'){e.preventDefault();undo();return;}
  if((e.ctrlKey||e.metaKey)&&(e.key.toLowerCase()==='y'||(e.shiftKey&&e.key.toLowerCase()==='z'))){e.preventDefault();redo();return;}
  if(e.key==='Enter'){const el=document.activeElement;if(el&&el.matches('.tile'))el.click();}
});

/* ---------- 测试钩子 + 证据场景（真实 DOM 点击路径） ---------- */
function logState(tag){
  const r=filteredRows();
  const f=Object.entries(state.filters).map(([d,s])=>d+':'+[...s].join('+')).join('|')||'-';
  console.log('[evidence:'+tag+'] projection='+state.projection+' filters='+f+' selection='+state.selection.size+' rows='+r.length+' snapshot='+(cur+1)+'/'+snapshots.length);
}
window.__prism={
  state:()=>({projection:state.projection,measure:state.measure,
    filters:Object.fromEntries(Object.entries(state.filters).map(([d,s])=>[d,[...s]])),
    selection:state.selection.size,rows:filteredRows().length,snapshots:snapshots.length,cursor:cur}),
  logState,
};
function qClick(sel){const el=document.querySelector(sel);if(el)el.click();else console.warn('[evidence] 元素缺失:',sel);}
function rowClick(i){const el=document.querySelectorAll('#tbody tr[data-act]')[i];if(el)el.click();else console.warn('[evidence] 行缺失:',i);}
(function evidenceScenario(){
  const m=location.hash.match(/evidence=(s\d)/);if(!m)return;
  const tag=m[1];scenarioMode=true; // 虚拟时间预算下 toast 保持显示，便于截图核对
  const steps=[];
  if(tag==='s2'||tag==='s3'||tag==='s4'){
    steps.push(()=>qClick('.tile[data-dim="cat"][data-val="c9"]'));   // 过滤：品类=护肤
    steps.push(()=>rowClick(0));steps.push(()=>rowClick(1));          // 选中前两行
  }
  if(tag==='s3'||tag==='s4'){
    steps.push(()=>qClick('[data-act="project"][data-dim="channel"]'));// 切换投影 → 渠道
  }
  if(tag==='s4'){
    steps.push(()=>qClick('[data-act="restore"][data-k="3"]'));        // 时间旅行回 #4
  }
  let i=0;(function next(){if(i<steps.length){steps[i++]();setTimeout(next,140);}else{logState(tag);}})();
})();

/* ---------- 启动（同步完成，首屏即可用） ---------- */
$('#dsMeta').textContent='数据集：零售订单快照 · '+fmtInt(ORDERS.length)+' 单 × 12 维 · 本地静态 · 无后端';
commit('初始状态','系统');
console.log('[prism] ready:',ORDERS.length,'orders,',Object.keys(DIMS).length,'dims, snapshots='+snapshots.length);
</script>
